import React, { useState } from 'react';
import { OrbSmall } from '../components/Orb';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score: 1, emoji: '😔', label: 'Very bad' },
  { score: 2, emoji: '😟', label: 'Bad' },
  { score: 3, emoji: '😐', label: 'Okay' },
  { score: 4, emoji: '🙂', label: 'Good' },
  { score: 5, emoji: '😄', label: 'Very good' },
];

const ACTIVITIES = [
  { id: 'workout',   icon: '🏃', label: 'Workout' },
  { id: 'social',    icon: '👥', label: 'Socialised' },
  { id: 'work',      icon: '💼', label: 'Work' },
  { id: 'nature',    icon: '🌿', label: 'Nature' },
  { id: 'creative',  icon: '🎨', label: 'Creative' },
  { id: 'screen',    icon: '📱', label: 'Lots of screen' },
  { id: 'alcohol',   icon: '🍷', label: 'Alcohol' },
  { id: 'meditation',icon: '🧘', label: 'Meditation' },
  { id: 'reading',   icon: '📖', label: 'Read' },
  { id: 'alone',     icon: '🌙', label: 'Alone time' },
  { id: 'conflict',  icon: '⚡', label: 'Conflict' },
  { id: 'goodsleep', icon: '😴', label: 'Slept well' },
  { id: 'badsleep',  icon: '🥴', label: 'Slept badly' },
  { id: 'goodfood',  icon: '🥗', label: 'Ate well' },
];

const PROG = ['20%', '42%', '64%', '84%', '100%'];

const css = {
  page: { background: '#EEEAE3', minHeight: '100vh', position: 'relative', overflowX: 'hidden' },
  inner: { padding: '72px 28px 110px', display: 'flex', flexDirection: 'column', minHeight: '100vh', animation: 'fadeIn 0.3s ease both' },
  stepNum: { fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.28)', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 12 },
  h: { fontSize: 36, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A', marginBottom: 8 },
  sub: { fontSize: 14, color: 'rgba(26,42,42,0.4)', marginBottom: 36, lineHeight: 1.5 },
  btnP: { width: '100%', padding: 18, borderRadius: 20, background: '#1A2A2A', color: '#EEEAE3', fontSize: 15, fontWeight: 600, letterSpacing: '-0.02em', border: 'none', cursor: 'pointer' },
  btnS: { width: '100%', padding: 15, borderRadius: 20, background: 'rgba(26,42,42,0.07)', color: '#2D6B6B', fontSize: 14, fontWeight: 500, border: 'none', cursor: 'pointer' },
  navBtns: { marginTop: 'auto', display: 'flex', flexDirection: 'column', gap: 10, paddingTop: 28 },
};

function ProgressBar({ step }) {
  return (
    <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 3, background: 'rgba(26,42,42,0.07)', zIndex: 50 }}>
      <div style={{ height: '100%', background: '#2D6B6B', borderRadius: '0 2px 2px 0', width: PROG[step - 1], transition: 'width 0.5s cubic-bezier(0.34,1,0.64,1)' }} />
    </div>
  );
}

function Slider({ label, id, leftLabel, rightLabel, value, onChange }) {
  const pct = ((value - 1) / 4) * 100;
  return (
    <div style={{ marginBottom: 28 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
        <span style={{ fontSize: 15, fontWeight: 600, color: '#1A2A2A', letterSpacing: '-0.02em' }}>{label}</span>
        <span style={{ fontSize: 22, fontWeight: 700, letterSpacing: '-0.04em', color: '#2D6B6B', minWidth: 28, textAlign: 'right' }}>{value}</span>
      </div>
      <div style={{ position: 'relative', height: 6, background: 'rgba(26,42,42,0.1)', borderRadius: 3, marginBottom: 8 }}>
        <div style={{ position: 'absolute', left: 0, top: 0, height: '100%', background: 'linear-gradient(90deg,#7EC8C8,#2D6B6B)', borderRadius: 3, width: pct + '%', pointerEvents: 'none', transition: 'width 0.1s' }} />
        <input type="range" min="1" max="5" step="1" value={value} onChange={e => onChange(parseInt(e.target.value))}
          style={{ position: 'absolute', width: '100%', height: '100%', top: 0, left: 0, opacity: 0, cursor: 'pointer', margin: 0, padding: 0 }} />
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <span style={{ fontSize: 11, color: 'rgba(26,42,42,0.3)', fontWeight: 500 }}>{leftLabel}</span>
        <span style={{ fontSize: 11, color: 'rgba(26,42,42,0.3)', fontWeight: 500 }}>{rightLabel}</span>
      </div>
    </div>
  );
}

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [step,       setStep]       = useState(1);
  const [mood,       setMood]       = useState(null);
  const [energy,     setEnergy]     = useState(3);
  const [anxiety,    setAnxiety]    = useState(3);
  const [sleep,      setSleep]      = useState(3);
  const [focus,      setFocus]      = useState(3);
  const [activities, setActivities] = useState([]);
  const [note,       setNote]       = useState('');

  const toggleActivity = (id) => {
    setActivities(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]);
  };

  const save = () => {
    const m = MOODS[mood];
    addMood(m.score, m.emoji, m.label, note, { energy, anxiety, sleep, focus, activities });
    setStep(5);
  };

  const reset = () => {
    setStep(1); setMood(null); setEnergy(3); setAnxiety(3);
    setSleep(3); setFocus(3); setActivities([]); setNote('');
  };

  const selActs = ACTIVITIES.filter(a => activities.includes(a.id));

  if (todayChecked && step !== 5) return (
    <div style={{ ...css.page, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ padding: '0 28px', textAlign: 'center' }}>
        <OrbSmall style={{ margin: '0 auto 32px' }} />
        <h2 style={{ fontSize: 34, fontWeight: 700, letterSpacing: '-0.05em', color: '#1A2A2A', marginBottom: 8 }}>Come back tomorrow.</h2>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginTop: 36 }}>
          <button onClick={() => setPage('history')} style={css.btnP}>See history</button>
          <button onClick={() => setPage('home')}    style={css.btnS}>Home</button>
        </div>
      </div>
    </div>
  );

  // ── STEP 1: Mood ──
  if (step === 1) return (
    <div style={css.page}>
      <ProgressBar step={1} />
      <div style={css.inner}>
        <div style={css.stepNum}>01 / 04</div>
        <h2 style={css.h}>How are<br />you today?</h2>
        <p style={css.sub}>Pick what feels right.</p>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 5 }}>
          {[...MOODS].reverse().map((m, i) => {
            const idx = 4 - i;
            const sel = mood === idx;
            return (
              <button key={m.score} onClick={() => setMood(idx)} style={{
                display: 'flex', alignItems: 'center', gap: 14,
                padding: '14px 18px', borderRadius: 18,
                background: sel ? 'rgba(255,255,255,0.82)' : 'rgba(255,255,255,0.38)',
                border: `1px solid ${sel ? 'rgba(45,107,107,0.3)' : 'rgba(255,255,255,0.65)'}`,
                boxShadow: sel ? '0 4px 20px rgba(45,107,107,0.1)' : 'none',
                transform: sel ? 'translateX(6px)' : 'none',
                transition: 'all 0.25s cubic-bezier(0.34,1.3,0.64,1)', cursor: 'pointer',
              }}>
                <span style={{ fontSize: 12, fontWeight: 600, color: sel ? '#2D6B6B' : 'rgba(26,42,42,0.18)', width: 16 }}>{m.score}</span>
                <span style={{ fontSize: 22 }}>{m.emoji}</span>
                <span style={{ fontSize: 16, fontWeight: 500, color: sel ? '#1A2A2A' : 'rgba(26,42,42,0.45)', letterSpacing: '-0.02em' }}>{m.label}</span>
                <span style={{ marginLeft: 'auto', fontSize: 13, color: sel ? '#2D6B6B' : 'rgba(26,42,42,0.12)' }}>›</span>
              </button>
            );
          })}
        </div>
        <div style={css.navBtns}>
          <button onClick={() => setStep(2)} disabled={mood === null} style={{ ...css.btnP, opacity: mood === null ? 0.28 : 1 }}>Next</button>
        </div>
      </div>
    </div>
  );

  // ── STEP 2: Sliders ──
  if (step === 2) return (
    <div style={css.page}>
      <ProgressBar step={2} />
      <div style={css.inner}>
        <div style={css.stepNum}>02 / 04</div>
        <h2 style={css.h}>How did your<br />body feel?</h2>
        <p style={css.sub}>Adjust the sliders.</p>
        <Slider label="Energy"  leftLabel="Exhausted"  rightLabel="Energised"     value={energy}  onChange={setEnergy} />
        <Slider label="Anxiety"  leftLabel="Calm"      rightLabel="Stressed" value={anxiety} onChange={setAnxiety} />
        <Slider label="Sleep"    leftLabel="Poor"     rightLabel="Bra"      value={sleep}   onChange={setSleep} />
        <Slider label="Focus"   leftLabel="Scattered" rightLabel="Sharp"    value={focus}   onChange={setFocus} />
        <div style={css.navBtns}>
          <button onClick={() => setStep(3)} style={css.btnP}>Next</button>
          <button onClick={() => setStep(1)} style={css.btnS}>← Back</button>
        </div>
      </div>
    </div>
  );

  // ── STEP 3: Activities ──
  if (step === 3) return (
    <div style={css.page}>
      <ProgressBar step={3} />
      <div style={css.inner}>
        <div style={css.stepNum}>03 / 04</div>
        <h2 style={css.h}>What did you<br />you today?</h2>
        <p style={css.sub}>Select all that apply.</p>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          {ACTIVITIES.map(a => {
            const sel = activities.includes(a.id);
            return (
              <button key={a.id} onClick={() => toggleActivity(a.id)} style={{
                display: 'flex', alignItems: 'center', gap: 6,
                padding: '11px 16px', borderRadius: 999,
                background: sel ? 'rgba(45,107,107,0.12)' : 'rgba(255,255,255,0.45)',
                border: `1px solid ${sel ? 'rgba(45,107,107,0.3)' : 'rgba(255,255,255,0.7)'}`,
                color: sel ? '#1A2A2A' : 'rgba(26,42,42,0.5)',
                fontSize: 14, fontWeight: 500,
                transform: sel ? 'scale(1.04)' : 'scale(1)',
                transition: 'all 0.2s cubic-bezier(0.34,1.3,0.64,1)',
              }}>
                <span style={{ fontSize: 16 }}>{a.icon}</span>{a.label}
              </button>
            );
          })}
        </div>
        <div style={css.navBtns}>
          <button onClick={() => setStep(4)} style={css.btnP}>Next</button>
          <button onClick={() => setStep(2)} style={css.btnS}>← Back</button>
        </div>
      </div>
    </div>
  );

  // ── STEP 4: Note ──
  if (step === 4) return (
    <div style={css.page}>
      <ProgressBar step={4} />
      <div style={css.inner}>
        <div style={css.stepNum}>04 / 04</div>
        <h2 style={css.h}>Last<br />thought.</h2>
        <p style={css.sub}>Optional. What shaped today?</p>
        <div style={{ flex: 1, padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)', display: 'flex', flexDirection: 'column', marginBottom: 14 }}>
          <textarea
            autoFocus
            value={note}
            onChange={e => setNote(e.target.value)}
            maxLength={500}
            placeholder="Today I felt…"
            style={{ flex: 1, background: 'transparent', border: 'none', outline: 'none', fontSize: 17, lineHeight: 1.7, color: '#1A2A2A', minHeight: 100, resize: 'none' }}
          />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          <button onClick={save} style={css.btnP}>Save entry →</button>
          <button onClick={() => setStep(3)} style={css.btnS}>← Back</button>
        </div>
      </div>
    </div>
  );

  // ── DONE ──
  const m = MOODS[mood];
  const summaryRows = [
    { k: 'Mood',      v: `${m.emoji} ${m.label}` },
    { k: 'Energy',     v: `${energy} / 5` },
    { k: 'Anxiety',     v: `${anxiety} / 5` },
    { k: 'Sleep',       v: `${sleep} / 5` },
    { k: 'Focus',      v: `${focus} / 5` },
    { k: 'Activities', v: selActs.length > 0 ? selActs.map(a => a.icon + ' ' + a.label).join(', ') : '—' },
    ...(note ? [{ k: 'Note', v: `"${note.slice(0, 60)}${note.length > 60 ? '…' : ''}"` }] : []),
  ];

  return (
    <div style={css.page}>
      <ProgressBar step={5} />
      <div style={css.inner}>
        <OrbSmall style={{ marginBottom: 32 }} />
        <h2 style={{ ...css.h, marginBottom: 4 }}>Saved<span style={{ color: '#2D6B6B' }}>.</span></h2>
        <p style={{ fontSize: 14, color: 'rgba(26,42,42,0.38)', marginBottom: 28 }}>Today's entry.</p>

        <div style={{ padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)', marginBottom: 20 }}>
          {summaryRows.map(({ k, v }, i) => (
            <div key={k} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', padding: '9px 0', borderBottom: i < summaryRows.length - 1 ? '1px solid rgba(26,42,42,0.06)' : 'none', gap: 12 }}>
              <span style={{ fontSize: 13, color: 'rgba(26,42,42,0.4)', fontWeight: 500, flexShrink: 0 }}>{k}</span>
              <span style={{ fontSize: 13, fontWeight: 600, color: '#1A2A2A', textAlign: 'right' }}>{v}</span>
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          <button onClick={() => setPage('history')} style={css.btnP}>See history</button>
          <button onClick={() => { reset(); setPage('home'); }} style={css.btnS}>Home</button>
        </div>
      </div>
    </div>
  );
}
